<script lang="ts">
 import OrganizationTree from "./OrganizationTree.svelte";
 import {Eye,EyeOff} from "@lucide/svelte";
 import {enter} from "./motion";
 import {onMount} from 'svelte';import {api} from './api';import type {Row} from './types';
 let {currentUser}:{currentUser:Row}=$props();
 let data:Row=$state({users:[],designations:[],companies:[],teams:[],lines:[],orders:[],history:[],capabilities:{},labels:{},permission_capabilities:{},permission_labels:{},products:[],roles:[],access_codes:{},buyers:[],production_areas:[]});
 let form:Row|null=$state(null),kind=$state('user'),tab=$state('Users'),search=$state(''),busy=$state(false),error=$state(''),notice=$state('');
 let passwordVisible=$state(false),confirmationVisible=$state(false),confirmationTouched=$state(false);
 let needsPassword=$derived.by(()=>!!form&&(kind==='user'||kind==='replace')&&(!form.id||!!form.password||!!form.password_confirmation));
 let passwordMismatch=$derived.by(()=>needsPassword&&confirmationTouched&&form?.password_confirmation!==form?.password);
 function resetPasswordControls(){passwordVisible=false;confirmationVisible=false;confirmationTouched=false}
 let designation=$derived(data.designations.find((d:Row)=>d.id===Number(form?.designation_id)));
 let visible=$derived((tab==='Designations'?data.designations:data.users).filter((x:Row)=>(x.name+' '+(x.username||'')+' '+(x.email||'')+' '+(x.phone||'')+' '+(x.department||'')+' '+(x.designation||'')+' '+(x.territory||'')).toLowerCase().includes(search.toLowerCase())));
 let visibleTeams=$derived(data.teams.filter((t:Row)=>(t.name+' '+(data.companies.find((c:Row)=>c.id===t.company_id)?.name||'')).toLowerCase().includes(search.toLowerCase())));
 function teamUsers(team:Row){return data.users.filter((u:Row)=>u.active&&u.scope==='team'&&u.companies.includes(team.company_id)&&u.teams.includes(team.id))}
 async function load(){data=await api('/setup-users')}
 onMount(()=>{load().catch(e=>error=e.message)});
 function edit(u?:Row){kind='user';error='';resetPasswordControls();form=u?{...structuredClone($state.snapshot(u)),features:[...u.setup_features],permissions:[...u.effective_permissions],password:'',password_confirmation:''}:{username:'',name:'',email:'',phone:'+91',password:data.local?'1234':'',password_confirmation:'',designation_id:data.designations.find((d:Row)=>d.name==='Junior Merchant')?.id||data.designations[0]?.id,inherit_designation:true,features:[],permissions:[],active:true,scope:'team',companies:[],teams:[],lines:[],orders:[],finishing_units:[],reports_to_id:0,territory:'',restrict_buyers:false,buyer_ids:[],production_areas:[]};changeDesignation()}
 function changeDesignation(){if(!form)return;const d=data.designations.find((d:Row)=>d.id===Number(form!.designation_id));if(!d)return;form.role=d.role;if(form.inherit_designation){form.features=[...d.features];form.permissions=[...d.permissions]}else{form.features=form.features.filter((f:string)=>d.features.includes(f));form.permissions=form.permissions.filter((p:string)=>d.permissions.includes(p))}}
 function editDesignation(d?:Row){kind='designation';error='';form=d?structuredClone($state.snapshot(d)):{name:'',department:'',role:'Marketing',features:[],permissions:[]}}
 function replace(u:Row){kind='replace';error='';resetPasswordControls();form={source_id:u.id,source_name:u.name,version:u.version,designation:u.designation,name:'',username:'',email:'',phone:'+91',password:data.local?'1234':'',password_confirmation:''}}
 function managerAllowed(candidate:Row){if(!candidate.active||candidate.is_developer||candidate.id===form?.id)return false;let u:Row|undefined=candidate;const seen=new Set<number>();while(u&&!seen.has(u.id)){if(u.id===form?.id)return false;seen.add(u.id);u=data.users.find((p:Row)=>p.id===u!.reports_to_id)}return true}
 function buyerOptions(){return data.buyers.filter((b:Row)=>form!.companies.includes(b.company_id)&&(form!.scope!=='team'||form!.teams.includes(b.team_id)))}
 function pruneBuyers(){if(form)form.buyer_ids=form.buyer_ids.filter((id:number)=>buyerOptions().some((b:Row)=>b.id===id))}
 function scopeChanged(){if(!form)return;form.production_areas=[];pruneBuyers()}
 function scopeLabel(u:Row){return ({company:'Assigned companies',team:'Buyer teams',line:'Sewing lines',po:'Purchase orders',cutting_table:'Cutting tables',finishing_line:'Finishing sub-lines'} as Record<string,string>)[u.scope]||u.scope}
 function resource(resourceKind='teams',companyId=data.companies[0]?.id||'',teamId=0){kind='resource';error='';form={kind:resourceKind,company_id:companyId,team_id:teamId||'',name:''}}
 function toggle(key:string,value:string|number,checked:boolean){if(!form)return;form[key]=checked?[...form[key],value]:form[key].filter((x:string|number)=>x!==value);if(key==='companies'){for(const resource of ['teams','lines','orders','production_areas'])form[resource]=form[resource].filter((id:number)=>data[resource].some((x:Row)=>x.id===id&&form!.companies.includes(x.company_id)))}if(key==='companies'||key==='teams')pruneBuyers()}
 function featureToggle(key:string,feature:string,checked:boolean){if(!form)return;let s=new Set<string>(form[key]);if(checked){s.add(feature);s.add(key==='features'?'view':feature.startsWith('export_')?'export_view':'view_orders');if(['create','submit','amend'].includes(feature))s.add('edit')}else{s.delete(feature);if(feature==='view')s.clear();if(feature==='view_orders')for(const v of s)if(!v.startsWith('export_'))s.delete(v);if(feature==='export_view')for(const v of s)if(v.startsWith('export_'))s.delete(v);if(feature==='edit')for(const v of ['create','submit','amend'])s.delete(v)}form[key]=[...s]}
 async function save(e:SubmitEvent){e.preventDefault();if(!form||busy)return;if(needsPassword&&form.password_confirmation!==form.password){confirmationTouched=true;const confirmation=(e.currentTarget as HTMLFormElement).elements.namedItem('password_confirmation');if(confirmation instanceof HTMLInputElement)confirmation.focus();return}busy=true;error='';try{let path=kind==='designation'?'/access-designations'+(form.id?'/'+form.id:''):kind==='replace'?'/setup-users/'+form.source_id+'/replace':kind==='resource'?'/access-resources':'/setup-users'+(form.id?'/'+form.id:'');let payload=form;if(kind==='user'&&form.id){const{password,password_confirmation,...access}=form;payload={...access,new_password:password,new_password_confirmation:password_confirmation}}const result=await api(path,payload);notice=kind==='replace'?`New employee account created. ${result.orders_transferred} unfinished POs and ${result.companies_transferred} company responsibilities and ${result.reports_transferred||0} reporting team members transferred. The previous account is disabled.`:kind==='designation'?'Designation saved. Users with changed access must sign in again.':kind==='resource'?(form.kind==='teams'?'Team created. Add its buyers, then assign users and the manager.':'Assignment resource added.'):'User access saved. Changes apply on the next sign-in.';if(result.welcome_email)notice+=result.welcome_email==='sent'?' Welcome email accepted for delivery.':result.welcome_email==='not_configured'?' Account created, but welcome email was not sent: configure the email sender.':' Account created, but welcome email was not sent. Check the email issue report; do not create the account again.';form=null;await load()}catch(e){error=(e as Error).message}finally{busy=false}}
 function dialog(node:HTMLDialogElement){node.showModal();const motion=enter(node);return{destroy(){motion.destroy();node.close()}}}
 function value(v:unknown):string{return Array.isArray(v)?v.join(', ')||'None':typeof v==='object'?JSON.stringify(v):String(v??'—')}
 function changes(detail:Row):string[]{if(!detail?.after)return [];return Object.keys(detail.after).filter(k=>JSON.stringify(detail.before?.[k])!==JSON.stringify(detail.after[k])).map(k=>`${k.replaceAll('_',' ')}: ${value(detail.before?.[k])} → ${value(detail.after[k])}`).concat(detail.password_reset?['Password reset; existing sessions ended.']:[])}
</script>
<div class="company-page-heading" use:enter={tab}><div><p class="eyebrow">ADMINISTRATION</p><h1>User access</h1><p>Designation rules, individual accounts and a complete handover history.</p></div><div class="row-actions"><button class="button secondary" onclick={()=>resource()}>Add team / buyer / area</button><button class="button primary" onclick={()=>tab==='Teams'?resource():tab==='Designations'?editDesignation():edit()}>{tab==='Teams'?'Create team':tab==='Designations'?'Add designation':'Add user'}</button></div></div>
{#if notice}<p class="company-notice" role="status">{notice}</p>{/if}{#if error&&!form}<p class="form-error" role="alert">{error}</p>{/if}
<section class="panel"><div class="company-register-toolbar"><div class="filter-tabs">{#each ['Users','Teams','Organisation tree','Designations','History'] as t}<button class:active={tab===t} onclick={()=>{tab=t;search=''}}>{t}</button>{/each}</div>{#if tab!=='History'}<input aria-label={tab==='Teams'?'Search teams':'Search users or designations'} placeholder={tab==='Teams'?'Search team or company':'Search name, department or designation'} bind:value={search}/>{/if}</div>
{#if tab==='Users'}<div class="table-wrap"><table><thead><tr><th>Employee</th><th>Contact details</th><th>Designation</th><th>Reports to</th><th>Login page</th><th>Access</th><th></th></tr></thead><tbody>{#each visible as u}<tr><td><strong>{u.name}</strong><br/><small>{u.employee_code} · {u.username}</small></td><td>{u.email||"Not added"}<br/><small>{u.phone||"No mobile number"}</small></td><td>{u.designation||u.role}<br/><small>{u.department}</small></td><td>{data.users.find((p:Row)=>p.id===u.reports_to_id)?.name||'Not assigned'}<br/><small>{u.territory}</small></td><td><a href={u.portal}>{u.portal}</a></td><td>{u.active?'Active':'Disabled'}<br/><small>{u.inherit_designation?'Designation rules':'Individual restrictions'} · {scopeLabel(u)}{u.restrict_buyers?' · '+u.buyer_ids.length+' buyers/brands':''}</small></td><td><div class="row-actions"><button class="button secondary" disabled={u.id===currentUser.id||u.is_developer} onclick={()=>edit(u)}>Edit access</button>{#if u.active&&u.id!==currentUser.id&&!u.is_developer}<button class="text-button" onclick={()=>replace(u)}>Replace employee</button>{/if}</div></td></tr>{/each}</tbody></table></div>
{:else if tab==='Teams'}
<div class="company-section"><h2>Buyer teams</h2><p class="muted">Create a team under an approved company, add its buyers / brands, then assign the manager and team members through Edit access. A manager can have any number of teams.</p><p class="muted">The people below have explicit team access. Company-wide access is broader and is not listed as team membership. Reporting relationships do not automatically grant order access.</p></div>
<div class="table-wrap"><table><thead><tr><th>Team / company</th><th>Buyers / brands</th><th>Assigned people</th><th>Actions</th></tr></thead><tbody>
{#each visibleTeams as team}<tr><td><strong>{team.name}</strong><br/><small>{data.companies.find((c:Row)=>c.id===team.company_id)?.name}</small></td><td>{#each data.buyers.filter((b:Row)=>b.team_id===team.id) as buyer}<p>{buyer.name}</p>{:else}<span class="muted">No buyers yet</span>{/each}</td><td>{#each teamUsers(team) as member}<div class="team-person"><span><strong>{member.name}</strong><br/><small>{member.designation||member.role}{member.territory?' · '+member.territory:''}</small></span><button class="text-button" disabled={member.id===currentUser.id||member.is_developer} onclick={()=>edit(member)} aria-label={'Edit access for '+member.name}>Edit access</button></div>{:else}<span class="muted">No users assigned. Open Users → Edit access and select this team.</span>{/each}</td><td><div class="row-actions"><button class="button secondary" onclick={()=>resource('buyers',team.company_id,team.id)}>Add buyer</button><button class="text-button" onclick={()=>{tab='Users';search=''}}>Assign existing user</button></div></td></tr>
{:else}<tr><td colspan="4" class="muted">{search?'No matching teams.':'No teams yet. Select Create team to get started.'}</td></tr>{/each}
</tbody></table></div>
{:else if tab==='Organisation tree'}<OrganizationTree users={data.users} currentUserId={currentUser.id} {search} onedit={edit}/>{:else if tab==='Designations'}<div class="table-wrap"><table><thead><tr><th>Department</th><th>Designation</th><th>Enabled features</th><th></th></tr></thead><tbody>{#each visible as d}<tr><td>{d.department}</td><td><strong>{d.name}</strong><br/><small>{d.role} permissions</small></td><td>{d.features.length+d.permissions.length}</td><td><button class="button secondary" disabled={d.role==='Super Admin'} onclick={()=>editDesignation(d)}>Configure</button></td></tr>{/each}</tbody></table></div>
{:else}<div class="company-section">{#each data.history as h}<article class="detail-card"><strong>{h.action}</strong><p>{h.subject_type} #{h.subject_id} · {h.actor} · {new Date(h.created_at).toLocaleString()}</p>{#if changes(h.detail).length}<details><summary>View changes</summary>{#each changes(h.detail) as change}<p class="muted">{change}</p>{/each}</details>{:else if h.detail?.from_user_id}<p>Employee ES-{String(h.detail.from_user_id).padStart(5,'0')} → ES-{String(h.detail.to_user_id).padStart(5,'0')}{h.detail.orders?' · '+h.detail.orders.length+' unfinished POs':''}</p>{/if}</article>{:else}<p class="muted">Access changes and employee handovers will appear here.</p>{/each}</div>{/if}</section>
<p class="muted">Permissions belong to designations. Each employee has a separate account. Company Setup KYC remains restricted to the existing Finance, MD and Super Admin rules.</p>
{#if form}<dialog use:dialog class="company-modal setup-users-modal" aria-label={kind==='replace'?'Replace employee':kind==='designation'?'Configure designation':kind==='resource'?'Add team or line':'User access'} oncancel={e=>{if(busy)e.preventDefault();else form=null}}><header><h2>{kind==='replace'?'Replace employee':kind==='designation'?'Configure designation':kind==='resource'?(form.kind==='teams'?'Create team':'Add buyer / production area'):form.id?'Edit user access':'Add user'}</h2><button type="button" class="button secondary" disabled={busy} onclick={()=>form=null}>Close</button></header><form onsubmit={save}>
{#if kind==='replace'}<p class="company-warning">This creates a new account with {form.source_name}’s designation and access, transfers all unfinished POs, company responsibilities and reporting team members, then disables the old account. Shipped POs remain locked and past work keeps its original author.</p><p><strong>{form.designation}</strong></p>{/if}
<div class="company-form-grid">
{#if kind==='user'||kind==='replace'}<label>Full name<input bind:value={form.name} maxlength="120" required/></label><label>Username<input bind:value={form.username} minlength="2" maxlength="80" required autocomplete="off" autocapitalize="none" spellcheck="false"/></label><label>Email address<input type="email" bind:value={form.email} required={!form.id} maxlength="254" autocomplete="off" placeholder="name@company.com"/><small>New users receive their role, responsibilities and private login details at this address.</small></label><label>Mobile / WhatsApp number<input type="tel" bind:value={form.phone} maxlength="50" autocomplete="off" placeholder="+91 98765 43210"/><small>India (+91) is the default. Use a different country code for overseas numbers.</small></label>
<label class="credential-field" for="initial-password">{form.id?'New password':'Initial password'}<span class="password-control"><input id="initial-password" name="password" type={passwordVisible?'text':'password'} bind:value={form.password} required={!form.id} minlength={data.local?4:12} maxlength="128" autocomplete="new-password" aria-describedby="initial-password-hint"/><button type="button" class="password-toggle" aria-label={(passwordVisible?'Hide ':'Show ')+(form.id?'new password':'initial password')} aria-controls="initial-password" aria-pressed={passwordVisible} onclick={()=>passwordVisible=!passwordVisible}>{#if passwordVisible}<EyeOff size={18}/>{:else}<Eye size={18}/>{/if}</button></span><small id="initial-password-hint">{form.id?'Leave blank to keep the current password. ':''}{data.local?'1234 is permitted only for local testing.':'Use 12–128 characters.'}</small></label>
<label class="credential-field" for="confirm-password">{form.id?'Confirm new password':'Confirm password'}<span class="password-control"><input id="confirm-password" name="password_confirmation" type={confirmationVisible?'text':'password'} bind:value={form.password_confirmation} required={needsPassword} minlength={data.local?4:12} maxlength="128" autocomplete="new-password" aria-invalid={passwordMismatch} aria-describedby={passwordMismatch?'confirm-password-error':'confirm-password-hint'} onblur={()=>confirmationTouched=true}/><button type="button" class="password-toggle" aria-label={confirmationVisible?'Hide confirmation password':'Show confirmation password'} aria-controls="confirm-password" aria-pressed={confirmationVisible} onclick={()=>confirmationVisible=!confirmationVisible}>{#if confirmationVisible}<EyeOff size={18}/>{:else}<Eye size={18}/>{/if}</button></span><small id="confirm-password-hint">{form.id?'Enter the same new password when changing it.':'Enter the same initial password again.'}</small></label>
{#if passwordMismatch}<p id="confirm-password-error" class="form-error wide" role="alert">Passwords do not match. Enter the same password in both fields.</p>{/if}
{/if}
{#if kind==='user'}<label class="wide">Designation<select bind:value={form.designation_id} onchange={changeDesignation}>{#each [...new Set(data.designations.map((d:Row)=>d.department))] as dept}<optgroup label={String(dept)}>{#each data.designations.filter((d:Row)=>d.department===dept) as d}<option value={d.id}>{d.name}</option>{/each}</optgroup>{/each}</select></label><label>Reports to<select bind:value={form.reports_to_id}><option value={0}>No reporting manager</option>{#each data.users.filter(managerAllowed) as manager}<option value={manager.id}>{manager.name} · {manager.designation||manager.role}</option>{/each}</select></label><label>Region / territory<input bind:value={form.territory} maxlength="120" placeholder="e.g. Asia, Europe or India"/></label><p class="wide muted">Reporting lines appear in the organisation tree. Assign the manager’s own record visibility below; reporting does not grant extra access.</p><label class="inline-check"><input type="checkbox" bind:checked={form.active}/>Account active</label><label class="inline-check"><input type="checkbox" bind:checked={form.inherit_designation} onchange={changeDesignation}/>Use designation permissions</label>{/if}
{#if kind==='designation'}<label>Department<input bind:value={form.department} maxlength="100" required list="access-departments"/><datalist id="access-departments">{#each [...new Set(data.designations.map((d:Row)=>d.department))] as dept}<option value={String(dept)}></option>{/each}</datalist></label><label>Designation name<input bind:value={form.name} maxlength="100" required/></label><label class="wide">Permission family<select bind:value={form.role} disabled={!!form.id} onchange={()=>{form!.features=[];form!.permissions=[]}}>{#each data.roles.filter((r:string)=>r!=='Super Admin') as role}<option>{role}</option>{/each}</select><small>This limits which features the designation can receive.</small></label>{/if}
{#if kind==='resource'}<label>Resource<select bind:value={form.kind}><option value="teams">Buyer team</option><option value="buyers">Buyer / brand</option><option value="lines">Sewing line</option><option value="cutting_table">Cutting table</option><option value="finishing_line">Finishing sub-line</option></select></label><label>Company<select bind:value={form.company_id} required><option value="">Choose company</option>{#each data.companies as c}<option value={c.id}>{c.name}</option>{/each}</select></label>{#if form.kind==='buyers'}<label class="wide">Assigned buyer team<select bind:value={form.team_id} required><option value="">Choose team</option>{#each data.teams.filter((t:Row)=>t.company_id===Number(form!.company_id)) as team}<option value={team.id}>{team.name}</option>{/each}</select></label>{/if}<label class="wide">Name<input bind:value={form.name} required maxlength="120" placeholder={form.kind==='teams'?'Team A':form.kind==='buyers'?'Buyer or brand name':form.kind==='cutting_table'?'Table 1':form.kind==='finishing_line'?'Trousers line 1':'Line 1'}/></label>{/if}
</div>
{#if kind==='user'||kind==='designation'}
{#each [['features','Company Setup',data.labels,kind==='designation'?data.capabilities[form.role]||[]:designation?.features||[]],['permissions','Export Documentation',data.permission_labels,(kind==='designation'?data.permission_capabilities[form.role]||[]:designation?.permissions||[]).filter((feature:string)=>feature.startsWith('export_'))],['permissions','Operations',data.permission_labels,(kind==='designation'?data.permission_capabilities[form.role]||[]:designation?.permissions||[]).filter((feature:string)=>!feature.startsWith('export_'))]] as group}<h3>{group[1]}</h3>{#if group[1]==='Export Documentation'}<p class="muted">Invoice entry, supporting documents, downloads and reviews. View access alone does not allow adding invoices.</p>{/if}<div class="access-checkboxes">{#each group[3] as feature}{#if feature!=='users'}<label class="inline-check"><input type="checkbox" checked={form[String(group[0])].includes(feature)} disabled={(kind==='user'&&form.inherit_designation)||form.role==='Super Admin'} onchange={e=>featureToggle(String(group[0]),feature,e.currentTarget.checked)}/><span><small class="permission-code">{data.access_codes?.[String(group[0])]?.[feature]||feature}</small>{group[2][feature]||feature}</span></label>{/if}{:else}<p class="muted">No features in this section.</p>{/each}</div>{/each}
{/if}
{#if kind==='user'&&form.permissions.length}
<h3>Company and order visibility</h3><p class="muted">Only approved internal companies appear here. With no company selected, the dashboard stays empty.</p><div class="access-checkboxes">{#each data.companies as c}<label class="inline-check"><input type="checkbox" checked={form.companies.includes(c.id)} onchange={e=>toggle('companies',c.id,e.currentTarget.checked)}/>{c.name}</label>{:else}<p>Approve an internal company first.</p>{/each}</div>
<label>Order visibility<select bind:value={form.scope} onchange={scopeChanged}><option value="company">All orders in assigned companies</option><option value="team">Selected buyer teams</option><option value="line">Selected sewing lines</option><option value="po">Selected purchase orders</option><option value="cutting_table">Selected cutting tables</option><option value="finishing_line">Selected finishing sub-lines</option></select></label>
{#if form.scope!=='company'}{@const key=form.scope==='team'?'teams':form.scope==='line'?'lines':form.scope==='po'?'orders':'production_areas'}<div class="access-checkboxes">{#each data[key].filter((x:Row)=>form!.companies.includes(x.company_id)&&(key!=='production_areas'||x.kind===form!.scope)) as item}<label class="inline-check"><input type="checkbox" checked={form[key].includes(item.id)} onchange={e=>toggle(key,item.id,e.currentTarget.checked)}/>{item.name||item.po} · {data.companies.find((c:Row)=>c.id===item.company_id)?.name}</label>{:else}<p class="muted">No matching assignments. Add a team or production area, or create an order first.</p>{/each}</div>{/if}
<h3>Buyer / brand restrictions</h3><label class="inline-check"><input type="checkbox" bind:checked={form.restrict_buyers} disabled={form.role==='Super Admin'}/>Limit this user to selected buyers / brands</label>{#if form.restrict_buyers}<p class="muted">This further limits the company, team, line or PO access above. Selecting no buyers hides all orders.</p><div class="access-checkboxes">{#each buyerOptions() as buyer}<label class="inline-check"><input type="checkbox" checked={form.buyer_ids.includes(buyer.id)} onchange={e=>toggle('buyer_ids',buyer.id,e.currentTarget.checked)}/>{buyer.name} · {data.teams.find((t:Row)=>t.id===buyer.team_id)?.name||'No team'}</label>{:else}<p class="muted">No buyers within the selected company / team assignments.</p>{/each}</div>{/if}
{#if form.role==='Finishing'}<h3>Finishing units</h3><div class="access-checkboxes">{#each data.products as unit}<label class="inline-check"><input type="checkbox" checked={form.finishing_units.includes(unit)} onchange={e=>toggle('finishing_units',unit,e.currentTarget.checked)}/>{unit}</label>{/each}</div>{/if}{/if}
{#if error}<p class="form-error" role="alert">{error}</p>{/if}<footer><button type="button" class="button secondary" disabled={busy} onclick={()=>form=null}>Cancel</button><button class="button primary" disabled={busy}>{busy?'Saving…':kind==='replace'?'Create replacement & transfer work':'Save'}</button></footer></form></dialog>{/if}

<style>
 .team-person{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:7px 0}.team-person+.team-person{border-top:1px solid #e7ecee}
 .permission-code{display:block;font-size:10px;font-weight:700;letter-spacing:.06em;color:#54717c;margin-bottom:3px}
 @media (min-width:1024px){.credential-field .password-control input{padding-right:52px}}
</style>
